field.formula:
SIZE(
    STR(
        ROUND(
            SUM_IF(
                MAX([close_adj] INCLUDE [trade_date]),
                MAX([trade_date] INCLUDE [trade_date]) =
                    MAX([trade_date] FIXED)
            ),
            2
        )
    ) + ' ₽',
    '36px'
)

